"""PISA 2012-2022 panel section: school loneliness, life satisfaction and digital use across waves (results/tables/pisa_panel_*.csv)."""
def build(ctx):
    pd, np, go = ctx.pd, ctx.np, ctx.go
    T = ctx.T; f = ctx.fmt
    S = pd.read_csv(T/"pisa_panel_samples.csv").set_index("year"); TR = pd.read_csv(T/"pisa_panel_trends.csv"); FE = pd.read_csv(T/"pisa_panel_fe.csv"); LDF = pd.read_csv(T/"pisa_panel_longdiff_fit.csv")
    H3 = pd.read_csv(T/"pisa_panel_h3_2015.csv"); HD = pd.read_csv(T/"pisa_panel_h3_desc.csv"); DO = pd.read_csv(T/"pisa_panel_dose.csv"); DS = pd.read_csv(T/"pisa_panel_dose_slope.csv"); ST = pd.read_csv(T/"pisa_panel_dose_steepen.csv"); PO = pd.read_csv(T/"pisa_panel_policy2018.csv")
    n_all = int(S.students.sum()); yrs = [2012, 2015, 2018, 2022]
    def tr(measure, sex, group, year, set_="balanced"):
        r = TR[(TR.measure == measure) & (TR.sex == sex) & (TR.group == group) & (TR.year == year) & (TR.set == set_)]; return float(r.value.iloc[0]) if len(r) else np.nan
    def ncty(measure, set_="balanced"):
        r = TR[(TR.measure == measure) & (TR.set == set_) & (TR.group == "all") & (TR.sex == "all")]; return int(r.n_countries.iloc[0]) if len(r) else 0
    pct = lambda v, d=1: f"{v:.{d}f}"

    # ---- chart 1: lonely at school and life satisfaction by wave, sex and OECD/partner (balanced country sets) -------------------------
    fig = ctx.make_subplots(rows=1, cols=2, subplot_titles=(f"Feels lonely at school, % agree (balanced set, {ncty('lonely')} systems)", f"Life satisfaction 0-10 (balanced set, {ncty('lifesat')} systems)"), horizontal_spacing=0.1)
    for col, (meas, ys) in enumerate([("lonely", yrs), ("lifesat", [2015, 2018, 2022])], start=1):
        for sex, colr in [("girls", ctx.GIRL), ("boys", ctx.BOY)]:
            for grp, dash in [("OECD", "solid"), ("partner", "dot")]:
                v = [tr(meas, sex, grp, y) for y in ys]
                fig.add_trace(go.Scatter(x=ys, y=v, mode="lines+markers", name=f"{sex}, {grp}", line=dict(color=colr, dash=dash, width=2.2), marker=dict(size=7), showlegend=(col == 1), hovertemplate="%{y:.2f}"), row=1, col=col)
    ctx.covid_band(fig, row=1, col=1); ctx.covid_band(fig, row=1, col=2)
    fig.update_xaxes(tickvals=yrs); fig.update_yaxes(title_text="% agree", row=1, col=1); fig.update_yaxes(title_text="mean, 0-10", row=1, col=2)
    ctx.figs["pisa_panel_trends"] = ctx.base(fig, h=400, hovermode="x")

    # ---- chart 2: 2015 ANXTEST x in-school / out-of-school use interaction coefficients by sex -----------------------------------------------
    H = H3[H3.anxiety == "ANXTEST (SD units)"]
    outs = [("lonely", "Lonely at school (pp)"), ("belong", "Belongs at school (pp)"), ("lifesat_low", "Life satisfaction 0-4 (pp)"), ("lifesat", "Life satisfaction (points x10)")]
    fig2 = ctx.make_subplots(rows=1, cols=2, subplot_titles=("Anxiety x in-school use (>1 h/weekday)", "Anxiety x out-of-school use (>4 h/weekday)"), shared_yaxes=True, horizontal_spacing=0.06)
    for col, (cc, ss) in enumerate([("anx_x_sch", "se_anx_x_sch"), ("anx_x_out", "se_anx_x_out")], start=1):
        for sex, colr, off in [("girls", ctx.GIRL, -0.17), ("boys", ctx.BOY, 0.17)]:
            xs, ys_, es = [], [], []
            for i, (y, lab) in enumerate(outs):
                r = H[(H.y == y) & (H.sex == sex)]
                if not len(r): continue
                sc = 10 if y == "lifesat" else 1
                xs.append(sc * float(r[cc].iloc[0])); es.append(sc * float(r[ss].iloc[0])); ys_.append(i + off)
            fig2.add_trace(go.Scatter(x=xs, y=ys_, mode="markers", name=sex, marker=dict(color=colr, size=9), error_x=dict(type="data", array=[1.96 * e for e in es], thickness=1.4), showlegend=(col == 1), hovertemplate="%{x:.2f}"), row=1, col=col)
        fig2.add_vline(x=0, line=dict(color=ctx.MUTED, width=1), row=1, col=col)
    fig2.update_yaxes(tickvals=list(range(len(outs))), ticktext=[l for _, l in outs], row=1, col=1); fig2.update_yaxes(tickvals=list(range(len(outs))), ticktext=["" for _ in outs], row=1, col=2)
    fig2.update_xaxes(title_text="coefficient per SD of test anxiety, 95% CI")
    ctx.figs["pisa_panel_h3"] = ctx.base(fig2, h=360, hovermode="closest")

    # ---- text numbers -------------------------------------------------------------------------------------------------------------------
    lon = {(s, g, y): tr("lonely", s, g, y) for s in ("girls", "boys") for g in ("OECD", "partner") for y in yrs}
    ls = {(s, g, y): tr("lifesat", s, g, y) for s in ("girls", "boys") for g in ("OECD", "partner") for y in (2015, 2018, 2022)}
    bel = {(s, y): tr("belong", s, "all", y) for s in ("girls", "boys") for y in yrs}
    hs = {y: tr("hrs_school", "all", "all", y) for y in (2012, 2015, 2018)}; ho = {y: tr("hrs_out", "all", "all", y) for y in (2012, 2015, 2018)}; o4 = {y: tr("out_4h", "all", "all", y) for y in (2012, 2015, 2018)}; s1 = {y: tr("sch_1h", "all", "all", y) for y in (2012, 2015, 2018)}
    def fe(outc, sex, sample="2012-2018", spec="hours", ctrl="escs"):
        r = FE[(FE.outcome == outc) & (FE.sex == sex) & (FE["sample"] == sample) & (FE.spec == spec) & (FE.controls == ctrl)]; return r.iloc[0] if len(r) else None
    fe_rows = []
    for outc, lab, d in [("lonely", "Lonely at school (pp)", 2), ("belong", "Belongs at school (pp)", 2), ("lifesat", "Life satisfaction (points)", 3), ("lifesat_low", "Life satisfaction 0-4 (pp)", 2)]:
        for sample in ["2012-2018", "2012-2022"]:
            cells = []
            for sex in ["girls", "boys"]:
                r = fe(outc, sex, sample)
                cells += [f(r.coef_school, r.se_school, d, 1.96), f(r.coef_out, r.se_out, d, 1.96)] if r is not None else ["", ""]
            r0 = fe(outc, "girls", sample)
            fe_rows.append([lab, sample, *cells, f"{int(r0.n_cells)} / {int(r0.n_countries)}" if r0 is not None else ""])
    fe_tbl = ctx.table(["Outcome (country means)", "Waves", "Girls: in-school h", "Girls: out-of-school h", "Boys: in-school h", "Boys: out-of-school h", "Cells / systems"], fe_rows)
    def ldf(period, outc, reg, sex):
        r = LDF[(LDF.period == period) & (LDF.outcome == outc) & (LDF.regressor == reg) & (LDF.sex == sex)]; return r.iloc[0] if len(r) else None
    ld_rows = []
    for period, outc, lab in [("2012->2018", "lonely", "Δ lonely at school (pp)"), ("2012->2018", "belong", "Δ belongs at school (pp)"), ("2015->2018", "lifesat", "Δ life satisfaction (points)"), ("2018->2022", "lifesat", "Δ life satisfaction (points), 2022 total device hours")]:
        for sex in ["girls", "boys"]:
            a, b = ldf(period, outc, "hrs_school", sex), ldf(period, outc, "hrs_out", sex)
            if a is None or b is None: continue
            ld_rows.append([lab, period.replace("->", " → "), sex, f"{a.mean_dy:+.2f}", f"{b.mean_dx:+.2f} h", f"{f(a.slope, a.se, 2)} (r = {a.r:.2f})", f"{f(b.slope, b.se, 2)} (r = {b.r:.2f})", int(a.n)])
    ld_tbl = ctx.table(["Change", "Period", "Sex", "Mean Δ outcome", "Mean Δ out-of-school h", "Slope on Δ in-school h (SE)", "Slope on Δ out-of-school h (SE)", "Systems"], ld_rows)

    def h3(y, sex, anx="ANXTEST (SD units)"):
        r = H3[(H3.y == y) & (H3.sex == sex) & (H3.anxiety == anx)]; return r.iloc[0] if len(r) else None
    h3_rows = []
    for y, lab, d in [("lonely", "Lonely at school (pp)", 2), ("belong", "Belongs at school (pp)", 2), ("lifesat", "Life satisfaction (points)", 3), ("lifesat_low", "Life satisfaction 0-4 (pp)", 2)]:
        for sex in ["girls", "boys"]:
            r = h3(y, sex)
            if r is None: continue
            h3_rows.append([lab, sex, f"{r.mean_y:.1f}", f(r.anx, r.se_anx, d, 1.96), f(r.sch_1h, r.se_sch, d, 1.96), f(r.out_4h, r.se_out, d, 1.96), f(r.anx_x_sch, r.se_anx_x_sch, d, 1.96), f(r.anx_x_out, r.se_anx_x_out, d, 1.96), f"{int(r.n):,}"])
    h3_tbl = ctx.table(["Outcome", "Sex", "Mean", "Test anxiety (per SD)", "In-school >1 h", "Out-of-school >4 h", "Anxiety × in-school", "Anxiety × out-of-school", "n"], h3_rows)
    hd = lambda sex, hi, col: float(HD[(HD.sex == sex) & (HD.hi_anx == hi)][col].iloc[0])
    r15 = h3("lonely", "all"); n15 = int(r15.n); c15 = int(r15.countries)

    def dose(year, sex, outc, band, col="coef"):
        r = DO[(DO.year == year) & (DO.sex == sex) & (DO.outcome == outc) & (DO.band == band)]; return float(r[col].iloc[0]) if len(r) else np.nan
    bands = ["none", "<=1 h", "1-2 h", "2-4 h", "4-6 h", ">6 h"]
    do_rows = []
    for outc, lab, ys_, d in [("lifesat", "Life satisfaction (points vs 1-2 h)", [2015, 2018, 2022], 2), ("lonely", "Lonely at school (pp vs 1-2 h)", [2012, 2015, 2018, 2022], 1)]:
        for y in ys_:
            for sex in ["girls", "boys"]:
                cells = [("ref." if b == "1-2 h" else f(dose(y, sex, outc, b), dose(y, sex, outc, b, "se"), d, 1.96)) for b in bands]
                shares = " / ".join(f"{dose(y, sex, outc, b, 'share'):.0f}" for b in bands)
                r = DO[(DO.year == y) & (DO.sex == sex) & (DO.outcome == outc)]
                do_rows.append([lab, f"{y}{' †' if y == 2022 else ''}", sex, *cells, shares, f"{int(r.n.sum()):,} / {int(r.countries.iloc[0])}" if len(r) else ""])
    do_tbl = ctx.table(["Outcome", "Wave", "Sex", "None", "≤1 h", "1-2 h", "2-4 h", "4-6 h", ">6 h", "% of students by band", "n / systems"], do_rows)
    def sl(year, sex, outc, col="slope_out"):
        r = DS[(DS.year == year) & (DS.sex == sex) & (DS.outcome == outc)]; return float(r[col].iloc[0]) if len(r) else np.nan
    st_ = lambda sex, outc, col: float(ST[(ST.sex == sex) & (ST.outcome == outc)][col].iloc[0])

    def po(y, sex):
        r = PO[(PO.y == y) & (PO.sex == sex)]; return r.iloc[0] if len(r) else None
    po_rows = []
    for y in ["chat_school_daily", "sch_1h", "hrs_school", "out_4h", "lonely", "belong", "lifesat", "lifesat_low", "belong_idx"]:
        r = po(y, "all")
        if r is None: continue
        d = 3 if y == "lifesat" else 2
        po_rows.append([r.outcome, *[f(po(y, s).coef, po(y, s).se, d, 1.96) if po(y, s) is not None else "" for s in ["all", "girls", "boys"]], f"{r['mean']:.1f} {r.unit}", f"{int(r.n):,} / {int(r.countries)}"])
    po_tbl = ctx.table(["Outcome", "All", "Girls", "Boys", "Mean", "n / systems"], po_rows)
    pol = po("lonely", "all")

    lit = ctx.table(["Study", "Data", "Finding"], [
        ["<a href='https://doi.org/10.1016/j.adolescence.2021.06.006'>Twenge, Haidt, Blake et al. 2021</a>, <em>J. Adolescence</em>", "PISA 2000-2018, 37 countries, n = 1,049,784", "School loneliness (6 ST034 items) rose 2012-2018 in 36 of 37 countries, more for girls; higher where smartphone access and internet use were higher; GDP, inequality and fertility unrelated (abstract)"],
        ["<a href='https://www.worldhappiness.report/ed/2026/social-media-is-harming-adolescents-at-a-scale-large-enough-to-cause-changes-at-the-population-level/'>Haidt and Rausch 2026</a>, World Happiness Report ch.", "PISA 2015-2018 life satisfaction, 47 systems", "40 of 47 systems showed significant declines 2015-2018, strong for both sexes; school loneliness up 2012-2018 in 34 of 35 countries"],
        ["<a href='https://doi.org/10.1787/9789264273856-en'>OECD 2017</a>, PISA 2015 Results Vol. III", "PISA 2015 well-being module", "OECD average life satisfaction 7.31; 11.8% at 0-4 (14% of girls, 9% of boys); 15% agree they feel lonely at school; 'extreme' internet users (>6 h/weekday outside school) 0.4 points lower life satisfaction and 17% lonely vs 12% of 1-2 h users"],
        ["<a href='https://doi.org/10.1787/acd78851-en'>OECD 2019</a>, PISA 2018 Results Vol. III", "PISA 2015 and 2018", "67% satisfied (7-10) in 2018, down 5 pp from 2015; agreement with 'I belong at school' and 'I make friends easily' down about 2 pp (OECD summary)"],
        ["<a href='https://econpapers.repec.org/RePEc:cca:wchild:121'>Mao and See 2025</a>, CHILD WP 121", "PISA 2015 and 2018 ICT module", "Early device exposure (age ≤6), instrumented by parental-occupation ICT intensity, raises school belonging at 15 with no clear effect on life satisfaction (abstract)"],
        ["<a href='https://doi.org/10.3389/fpsyg.2026.1740535'>Fang and Mo 2026</a>, <em>Front. Psychol.</em>", "PISA 2022, n = 41,490", "School digitalisation (IC172) and life satisfaction: direct β = 0.032 in a PLS-SEM; cross-sectional, small effects"]])

    html = f"""<h3 id="pisa_panel">PISA 2012–2022: school loneliness, life satisfaction and digital use across waves</h3>
<p>PISA has asked 15-year-olds the same six sense-of-belonging statements since 2000 ("I feel lonely at school", "I feel like I belong at school", ...), a 0–10 life-satisfaction question since 2015, and, in the systems that chose the ICT familiarity module, how long they spend on the Internet on a typical weekday at school and outside school (2012, 2015 and 2018; identical seven categories from "no time" to "more than 6 hours"). PISA 2022 replaced the Internet items with hours per day on digital resources for learning and for leisure, at school and before/after school, which we sum to total device hours and flag wherever 2022 enters a digital-use comparison. Stacking the four public-use files gives {n_all:,} students: {int(S.loc[2012,'students']):,} in {int(S.loc[2012,'countries'])} systems in 2012 ({int(S.loc[2012,'ict_countries'])} with the ICT module), {int(S.loc[2015,'students']):,} in {int(S.loc[2015,'countries'])} in 2015 ({int(S.loc[2015,'ict_countries'])}), {int(S.loc[2018,'students']):,} in {int(S.loc[2018,'countries'])} in 2018 ({int(S.loc[2018,'ict_countries'])}) and {int(S.loc[2022,'students']):,} in {int(S.loc[2022,'countries'])} in 2022. Life satisfaction is available for {int(S.loc[2015,'countries_lifesat'])}, {int(S.loc[2018,'countries_lifesat'])} and {int(S.loc[2022,'countries_lifesat'])} systems in 2015, 2018 and 2022. In 2012 the belonging block sat in two of the three rotated questionnaire forms, so about a third of students have no belonging items by design; all estimates use the final student weights. The 2015 wave also carries the five-item test-anxiety scale (ANXTEST: "I often worry that it will be difficult for me to take a test", "I worry that I will get poor grades at school", "Even if I am well prepared for a test I feel very anxious", "I get very tense when I study", "I get nervous when I don't know how to solve a task at school"), which is the direct schoolwork-anxiety measure that the Phase 1 H3 test had to proxy with mathematics anxiety in 2022.</p>
<h4>Trends</h4>
{ctx.fig_div('pisa_panel_trends')}
<p class="caption">Unweighted means of weighted country means, restricted to systems that asked the item in every wave shown (balanced sets). Solid lines are OECD members, dotted lines partner systems. Life satisfaction was first asked in 2015. The grey band marks 2020.</p>
<p>Among OECD systems, the share of girls who agree they feel lonely at school moved from {pct(lon[('girls','OECD',2012)])}% in 2012 to {pct(lon[('girls','OECD',2015)])}% in 2015, {pct(lon[('girls','OECD',2018)])}% in 2018 and {pct(lon[('girls','OECD',2022)])}% in 2022; for boys the path is {pct(lon[('boys','OECD',2012)])}% → {pct(lon[('boys','OECD',2015)])}% → {pct(lon[('boys','OECD',2018)])}% → {pct(lon[('boys','OECD',2022)])}%. Partner systems started higher ({pct(lon[('girls','partner',2012)])}% of girls, {pct(lon[('boys','partner',2012)])}% of boys in 2012) and reached {pct(lon[('girls','partner',2022)])}% and {pct(lon[('boys','partner',2022)])}% in 2022. Agreement with "I feel like I belong at school" fell from {pct(bel[('girls',2012)])}% to {pct(bel[('girls',2022)])}% among girls and from {pct(bel[('boys',2012)])}% to {pct(bel[('boys',2022)])}% among boys across all systems in the balanced set. Mean life satisfaction among OECD girls went from {ls[('girls','OECD',2015)]:.2f} in 2015 to {ls[('girls','OECD',2018)]:.2f} in 2018 and {ls[('girls','OECD',2022)]:.2f} in 2022, against {ls[('boys','OECD',2015)]:.2f}, {ls[('boys','OECD',2018)]:.2f} and {ls[('boys','OECD',2022)]:.2f} for boys, so the sex gap in life satisfaction widened from {ls[('boys','OECD',2015)]-ls[('girls','OECD',2015)]:.2f} to {ls[('boys','OECD',2022)]-ls[('girls','OECD',2022)]:.2f} points. Over the same years weekday Internet time in the ICT-module systems rose from {ho[2012]:.2f} hours outside school and {hs[2012]:.2f} hours at school in 2012 to {ho[2018]:.2f} and {hs[2018]:.2f} hours in 2018; the share above 4 hours outside school went from {o4[2012]:.0f}% to {o4[2018]:.0f}% and the share above 1 hour at school from {s1[2012]:.0f}% to {s1[2018]:.0f}%. The largest single step in loneliness is 2012 → 2015, the wave in which most systems moved from paper to computer-delivered questionnaires and the belonging block left the rotated design; the 2015 → 2022 changes are smaller and, for OECD boys, flat.</p>
<h4>Within-country panel: did well-being fall more where digital hours rose more?</h4>
<p>The country-sex-wave means are regressed on the mean in-school and out-of-school weekday hours with country and wave fixed effects, so that the estimates use only within-country changes net of the common wave trend; the mean ESCS of the cell is controlled and standard errors are clustered by country. The 2012–2018 rows use the identical Internet-hours item; the 2012–2022 rows add the 2022 total device hours.</p>
{fe_tbl}
<p class="caption">Coefficient per additional hour per weekday (SE); bold when |t| &gt; 1.96. Cells are country × sex × wave means for ICT-module systems observed in at least two waves. Life satisfaction rows start in 2015.</p>
<p>With country and wave effects removed, changes in out-of-school hours do not track changes in loneliness ({f(fe('lonely','girls').coef_out, fe('lonely','girls').se_out)} pp per hour for girls and {f(fe('lonely','boys').coef_out, fe('lonely','boys').se_out)} for boys over 2012–2018) or in life satisfaction ({f(fe('lifesat','girls').coef_out, fe('lifesat','girls').se_out, 3)} and {f(fe('lifesat','boys').coef_out, fe('lifesat','boys').se_out, 3)} points per hour), but they do track the fall in school belonging: agreement that one belongs at school moves by {f(fe('belong','girls').coef_out, fe('belong','girls').se_out)} pp per additional out-of-school hour among girls and {f(fe('belong','boys').coef_out, fe('belong','boys').se_out)} among boys, an association that weakens to {f(fe('belong','girls','2012-2022').coef_out, fe('belong','girls','2012-2022').se_out)} and {f(fe('belong','boys','2012-2022').coef_out, fe('belong','boys','2012-2022').se_out)} once the 2022 total-device item is added. In-school hours add nothing beyond that. The long differences show the same pattern. Between 2012 and 2018 the loneliness share rose by {ldf('2012->2018','lonely','hrs_out','girls').mean_dy:+.1f} pp among girls and {ldf('2012->2018','lonely','hrs_out','boys').mean_dy:+.1f} pp among boys in the {int(ldf('2012->2018','lonely','hrs_out','girls').n)} systems with the ICT module in both waves, while out-of-school hours rose by {ldf('2012->2018','lonely','hrs_out','girls').mean_dx:+.2f} hours; the cross-country slope of the loneliness change on the hours change is {f(ldf('2012->2018','lonely','hrs_out','girls').slope, ldf('2012->2018','lonely','hrs_out','girls').se)} pp per hour for girls (r = {ldf('2012->2018','lonely','hrs_out','girls').r:.2f}) and {f(ldf('2012->2018','lonely','hrs_out','boys').slope, ldf('2012->2018','lonely','hrs_out','boys').se)} for boys (r = {ldf('2012->2018','lonely','hrs_out','boys').r:.2f}), whereas belonging changed by {ldf('2012->2018','belong','hrs_out','girls').mean_dy:+.1f} pp among girls and {ldf('2012->2018','belong','hrs_out','boys').mean_dy:+.1f} pp among boys with slopes of {f(ldf('2012->2018','belong','hrs_out','girls').slope, ldf('2012->2018','belong','hrs_out','girls').se)} (r = {ldf('2012->2018','belong','hrs_out','girls').r:.2f}) and {f(ldf('2012->2018','belong','hrs_out','boys').slope, ldf('2012->2018','belong','hrs_out','boys').se)} (r = {ldf('2012->2018','belong','hrs_out','boys').r:.2f}) pp per hour. The 2015 → 2018 fall in life satisfaction ({ldf('2015->2018','lifesat','hrs_out','girls').mean_dy:+.2f} points for girls, {ldf('2015->2018','lifesat','hrs_out','boys').mean_dy:+.2f} for boys) is unrelated to the hours change ({f(ldf('2015->2018','lifesat','hrs_out','girls').slope, ldf('2015->2018','lifesat','hrs_out','girls').se)} and {f(ldf('2015->2018','lifesat','hrs_out','boys').slope, ldf('2015->2018','lifesat','hrs_out','boys').se)} points per hour).</p>
{ld_tbl}
<p class="caption">Long differences in weighted country means; slopes from OLS across systems with heteroskedasticity-robust SEs.</p>
<h4>PISA 2015: test anxiety × in-school versus out-of-school Internet use (H3)</h4>
<p>H3 predicts that the harmful association of digital use is concentrated among students under academic pressure and for use inside the school day. PISA 2015 is the one wave with a direct schoolwork-anxiety scale and the weekday hours split by location, in {c15} ICT-module systems ({n15:,} students with anxiety, hours, ESCS and grade). Students above their country's median test anxiety are not heavier in-school users: {hd('all',1,'sch_1h'):.1f}% of them exceed 1 hour at school against {hd('all',0,'sch_1h'):.1f}% of lower-anxiety students, and {hd('all',1,'out_4h'):.1f}% versus {hd('all',0,'out_4h'):.1f}% exceed 4 hours outside school. The regressions below interact standardised ANXTEST with both use indicators, with country fixed effects, ESCS and grade, student weights and school-clustered SEs.</p>
{ctx.fig_div('pisa_panel_h3')}
<p class="caption">Interaction coefficients (per SD of test anxiety) with 95% confidence intervals; the life-satisfaction coefficient is multiplied by 10 for display. A positive value for loneliness or low life satisfaction, or a negative value for belonging or life satisfaction, means the use indicator is more harmful for anxious students.</p>
{h3_tbl}
<p class="caption">Main effects are evaluated at mean anxiety; the interaction is the change in the use coefficient per SD of ANXTEST. Binary outcomes in percentage points, life satisfaction in points on the 0–10 scale.</p>
<p>Test anxiety itself is strongly associated with worse outcomes: one SD raises girls' loneliness by {h3('lonely','girls').anx:.1f} pp (boys {h3('lonely','boys').anx:.1f}) and lowers life satisfaction by {-h3('lifesat','girls').anx:.2f} points (boys {-h3('lifesat','boys').anx:.2f}). In-school Internet use above 1 hour is itself linked to more loneliness ({f(h3('lonely','girls').sch_1h, h3('lonely','girls').se_sch)} pp for girls, {f(h3('lonely','boys').sch_1h, h3('lonely','boys').se_sch)} for boys) whereas heavy out-of-school use mainly lowers life satisfaction ({f(h3('lifesat','girls').out_4h, h3('lifesat','girls').se_out)} points for girls, {f(h3('lifesat','boys').out_4h, h3('lifesat','boys').se_out)} for boys). The interactions are the H3 test proper: for loneliness the anxiety × in-school term is {f(h3('lonely','girls').anx_x_sch, h3('lonely','girls').se_anx_x_sch)} pp for girls and {f(h3('lonely','boys').anx_x_sch, h3('lonely','boys').se_anx_x_sch)} for boys, against anxiety × out-of-school terms of {f(h3('lonely','girls').anx_x_out, h3('lonely','girls').se_anx_x_out)} and {f(h3('lonely','boys').anx_x_out, h3('lonely','boys').se_anx_x_out)}; for life satisfaction the in-school interactions are {f(h3('lifesat','girls').anx_x_sch, h3('lifesat','girls').se_anx_x_sch, 3)} and {f(h3('lifesat','boys').anx_x_sch, h3('lifesat','boys').se_anx_x_sch, 3)} points, the out-of-school interactions {f(h3('lifesat','girls').anx_x_out, h3('lifesat','girls').se_anx_x_out, 3)} and {f(h3('lifesat','boys').anx_x_out, h3('lifesat','boys').se_anx_x_out, 3)}. Every interaction that is distinguishable from zero has the sign opposite to H3's prediction: among more anxious students heavy use is less, not more, strongly associated with loneliness and low life satisfaction, and in-school use is not singled out. The above-median anxiety split and the continuous-hours version (results/tables/pisa_panel_h3_2015.csv) give the same picture.</p>
<h4>Dose–response by wave</h4>
{do_tbl}
<p class="caption">Country-fixed-effect contrasts against students at 1–2 hours per weekday outside school (SE), controlling ESCS and grade, student weights, school-clustered SEs; ICT-module systems only. † 2022 bands are total weekday hours on digital resources before and after school (learning plus leisure), not Internet hours, so 2022 levels are not comparable with earlier waves.</p>
<p>Within every wave the relationship is J-shaped rather than linear. Students who report no Internet use outside school are lonelier and less satisfied than those at 1–2 hours (girls' life satisfaction {f(dose(2015,'girls','lifesat','none'), dose(2015,'girls','lifesat','none','se'))} points in 2015 and {f(dose(2018,'girls','lifesat','none'), dose(2018,'girls','lifesat','none','se'))} in 2018), the 1–2 hour band is the best-off group, and above 2 hours the gradient is monotone and steeper for girls: at more than 6 hours girls' life satisfaction is {f(dose(2015,'girls','lifesat','>6 h'), dose(2015,'girls','lifesat','>6 h','se'))} points below the 1–2 hour band in 2015, {f(dose(2018,'girls','lifesat','>6 h'), dose(2018,'girls','lifesat','>6 h','se'))} in 2018 and {f(dose(2022,'girls','lifesat','>6 h'), dose(2022,'girls','lifesat','>6 h','se'))} in 2022 (boys {f(dose(2015,'boys','lifesat','>6 h'), dose(2015,'boys','lifesat','>6 h','se'))}, {f(dose(2018,'boys','lifesat','>6 h'), dose(2018,'boys','lifesat','>6 h','se'))} and {f(dose(2022,'boys','lifesat','>6 h'), dose(2022,'boys','lifesat','>6 h','se'))}), and the share of girls at 0–4 is {f(dose(2015,'girls','lifesat_low','>6 h'), dose(2015,'girls','lifesat_low','>6 h','se'))}, {f(dose(2018,'girls','lifesat_low','>6 h'), dose(2018,'girls','lifesat_low','>6 h','se'))} and {f(dose(2022,'girls','lifesat_low','>6 h'), dose(2022,'girls','lifesat_low','>6 h','se'))} pp higher. Meanwhile the share of girls above 4 hours went from {dose(2015,'girls','lifesat','4-6 h','share')+dose(2015,'girls','lifesat','>6 h','share'):.0f}% in 2015 to {dose(2018,'girls','lifesat','4-6 h','share')+dose(2018,'girls','lifesat','>6 h','share'):.0f}% in 2018. Pooling 2015 and 2018 for the {int(ST.countries.iloc[0])} systems with the ICT module in both waves, the linear slope of life satisfaction on out-of-school hours was {f(st_('girls','lifesat','slope_out_2015'), st_('girls','lifesat','se_2015'), 3)} points per hour for girls in 2015 and changed by {f(st_('girls','lifesat','change_2018'), st_('girls','lifesat','se_change'), 3)} in 2018 (boys {f(st_('boys','lifesat','slope_out_2015'), st_('boys','lifesat','se_2015'), 3)} and {f(st_('boys','lifesat','change_2018'), st_('boys','lifesat','se_change'), 3)}); for loneliness the 2015 slopes are {f(st_('girls','lonely','slope_out_2015'), st_('girls','lonely','se_2015'))} and {f(st_('boys','lonely','slope_out_2015'), st_('boys','lonely','se_2015'))} pp per hour with 2018 changes of {f(st_('girls','lonely','change_2018'), st_('girls','lonely','se_change'))} and {f(st_('boys','lonely','change_2018'), st_('boys','lonely','se_change'))}. The in-school slope on loneliness is {f(st_('girls','lonely','slope_school_2015'), st_('girls','lonely','se_school_2015'))} pp per hour for girls and {f(st_('boys','lonely','slope_school_2015'), st_('boys','lonely','se_school_2015'))} for boys in 2015, several times the out-of-school slope per hour, with 2018 changes of {f(st_('girls','lonely','change_school_2018'), st_('girls','lonely','se_change_school'))} and {f(st_('boys','lonely','change_school_2018'), st_('boys','lonely','se_change_school'))}. The per-hour life-satisfaction gradient therefore steepened by roughly a third between 2015 and 2018 for both sexes, while the loneliness gradients did not move; the flatter 2022 gradient is measured on a different item and is not comparable.</p>
<h4>2018: schools with a written policy on digital-device use</h4>
<p>No PISA wave before 2022 asked principals about phone bans, so the 2022 within-country ban comparison cannot be replicated backwards. The closest earlier item is PISA 2018 SC156Q01HA, whether the school has "its own written statement about the use of digital devices": {pol.share_policy:.0f}% of students in {int(pol.countries)} systems ({int(pol.n_schools):,} schools) attended such a school. A written statement is a much weaker treatment than a ban and is as likely to accompany device-rich teaching as device restriction.</p>
{po_tbl}
<p class="caption">Within-country comparison of students in schools with and without a written digital-device policy in 2018 (same specification as the 2022 phone-ban table: ESCS, private/public, grade, sex; country FE; student weights; school-clustered SEs). The ICT-module outcomes cover fewer systems.</p>
<h4>Related literature</h4>
{lit}
<div class="note"><strong>Assessment.</strong> The four-wave panel confirms the descriptive premise shared by H1 and H2: between 2012 and 2022 school loneliness rose, belonging fell and life satisfaction fell in most systems, more for girls, while weekday Internet time outside school in the ICT-module systems went from {ho[2012]:.1f} to {ho[2018]:.1f} hours. Three findings qualify the timing-based reading. First, the largest loneliness step is 2012 → 2015, which coincides with the move to computer-delivered questionnaires, so part of the published 2012–2018 trend (Twenge et al. 2021) may be a mode effect (H0). Second, within countries, systems where out-of-school hours rose more did not see loneliness rise more or life satisfaction fall more (two-way fixed-effects coefficients near zero), although school belonging did fall more there ({f(fe('belong','girls').coef_out, fe('belong','girls').se_out)} pp per hour for girls, {f(fe('belong','boys').coef_out, fe('belong','boys').se_out)} for boys, 2012–2018); as in the HBSC pressure panel, most of the change is a common wave shift. Third, at the student level the association is J-shaped and present in every wave, steeper for girls, and the per-hour life-satisfaction gradient steepened significantly between 2015 and 2018 ({f(st_('girls','lifesat','change_2018'), st_('girls','lifesat','se_change'), 3)} points per hour for girls, {f(st_('boys','lifesat','change_2018'), st_('boys','lifesat','se_change'), 3)} for boys), consistent with H1's claim that heavy use became more harmful as it became heavier, though the 2022 item gives a flatter gradient. For H3 the 2015 test is informative in a way the 2022 mathematics-anxiety proxy was not: in-school Internet use is tied to school loneliness ({f(st_('girls','lonely','slope_school_2015'), st_('girls','lonely','se_school_2015'))} and {f(st_('boys','lonely','slope_school_2015'), st_('boys','lonely','se_school_2015'))} pp per hour, several times the out-of-school slope) but not to lower life satisfaction, whereas out-of-school use is tied to lower life satisfaction and barely to loneliness; and test anxiety, the strongest correlate of every outcome, does not amplify either association, the anxiety × use interactions being small and of the opposite sign. The sharp form of H3 (digital harm concentrated among anxious students during the school day) is therefore not supported in 2015, while the location-specific form (in-school use relates to school loneliness) is. The 2018 written-policy item is not a ban: schools with a policy have slightly more in-school use ({f(po('sch_1h','all').coef, po('sch_1h','all').se)} pp above 1 hour) yet slightly less loneliness ({f(pol.coef, pol.se)} pp) and higher belonging, which points to school-quality selection rather than restriction. All within-wave estimates are cross-sectional; the panel component rests on {int(fe('lonely','all').n_countries)} systems observed two to three times (2012–2018).</div>"""
    return {"pisa_panel": html}
